#!/usr/bin/env bash
# pe-read.sh SEAT CX CY — creep cluster read: turrets within 40 of (CX,CY) hp/ammo, enemy units by name within 70, spawners/worms hp, seat hp, evo, tick
S=$1
/home/tony/agentic_workspace/projects/game-bot/factorio/research/lib/act.sh exec_lua $S code="local s=game.surfaces[1] local o={'tick '..game.tick} local tot=0 for _,e in pairs(s.find_entities_filtered{name='gun-turret',force='player',position={$2,$3},radius=40}) do local n=e.get_inventory(defines.inventory.turret_ammo).get_item_count() tot=tot+n o[#o+1]=string.format('T%.0f,%.0f:%.0fhp:%d',e.position.x,e.position.y,e.health,n) end o[#o+1]='ammo '..tot local r={} for _,e in pairs(s.find_entities_filtered{force='enemy',position={$2,$3},radius=70,type='unit'}) do r[e.name]=(r[e.name] or 0)+1 end for k,v in pairs(r) do o[#o+1]=k..'='..v end for _,e in pairs(s.find_entities_filtered{force='enemy',position={387,-393},radius=60,type={'unit-spawner','turret'}}) do o[#o+1]=string.format('%s(%.0f,%.0f)%.0f',e.name:gsub('%-turret',''),e.position.x,e.position.y,e.health) end local c=game.players['$S'].character o[#o+1]=string.format('seat %.0f at %.0f,%.0f fol %d evo %.4f',c.health,c.position.x,c.position.y,#c.following_robots,game.forces.enemy.get_evolution_factor(1)) rcon.print(table.concat(o,' '))" | jq -r .output
